  "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\n// Get a free hosted Postgres database in seconds: `npx create-db`\n\ngenerator zod {\n  provider         = \"zod-prisma-types\"\n  output           = \"../generated/zod\"\n  createInputTypes = false\n  modelSuffix      = \"\"\n}\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// 1. QUẢN LÝ TÁC NHÂN (USERS)\n// Lưu trữ thông tin phân quyền cho 4 nhóm tác nhân dựa trên địa chỉ ví cá nhân.\nenum Role {\n  FARMER // Nông dân\n  SHIPPER // Nhà vận chuyển\n  RETAILER // Nhà bán lẻ\n  CONSUMER // Người tiêu dùng\n}\n\nmodel User {\n  id            String   @id @default(uuid())\n  walletAddress String   @unique // Địa chỉ ví MetaMask (Dùng làm Khóa chính logic để xác thực)\n  fullName      String\n  email         String?  @unique\n  phone         String?\n  role          Role     @default(CONSUMER)\n  companyId     String\n  company       Company  @relation(fields: [companyId], references: [id])\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  // Mối quan hệ từ các bảng khác\n  batchesCreated Batch[]       @relation(\"FarmerBatches\")\n  transports     StepTransit[] @relation(\"ShipperTransports\")\n  qualityTests   QualityTest[] @relation(\"RetailerTests\")\n}\n\nenum OrganizationType {\n  FARMER\n  SHIPPER\n  RETAILER\n}\n\nmodel Company {\n  id              String           @id @default(uuid())\n  type            OrganizationType // Dùng Enum thay cho Boolean\n  companyName     String\n  location        String\n  protectedKey    String // Dùng để gia nhập\n  members         User[]\n  shippedBatches  Batch[]          @relation(\"ShipperBatches\") // Danh sách các lô hàng công ty này đi giao\n  retailedBatches Batch[]          @relation(\"RetailerBatches\") // Danh sách các lô hàng siêu thị này bày bán\n}\n\n// 2. QUẢN LÝ LÔ HÀNG (BATCHES)\n// Đây là bảng cốt lõi, liên kết trực tiếp với dữ liệu On-chain qua chuỗi định danh Batch ID.\nenum BatchStatus {\n  PLANTED // Đã gieo trồng\n  HARVESTED // Đã thu hoạch\n  IN_TRANSIT // Đang trong quá trình vận chuyển\n  TESTING // Đang kiểm tra\n  RETAILING // Đã đến nhà bán lẻ / Đang trên kệ hàng\n  SOLD // Đã bán cho người tiêu dùng\n  ABORTED // Đã hủy\n}\n\nenum Category {\n  VEGETABLE\n  FRUIT\n  GRAIN\n  BEAN\n  HERB\n  OTHER\n}\n\nmodel ActivityLog {\n  id          String   @id @default(uuid())\n  batchId     String\n  batch       Batch    @relation(fields: [batchId], references: [id])\n  description String // \"Bón phân đợt 1\"\n  timestamp   DateTime @default(now())\n}\n\nmodel Batch {\n  id             String        @id @default(uuid()) // ID sinh tự động ở Hệ thống Off-chain\n  blockchainId   String        @unique // ID tương ứng lưu trên Smart Contract (Đồng bộ sau khi Tx hoàn tất)\n  plantTxHash    String? // Transaction Hash lúc tạo lô hàng để đối chiếu e-etherscan\n  harvestTxHash  String? // Transaction Hash lúc thu hoạch để đối chiếu e-etherscan\n  shipTxHash     String? // Transaction Hash lúc giao cho Shipper để đối chiếu e-etherscan\n  productName    String\n  productVariety String // Giống cây trồng\n  category       Category      @default(VEGETABLE)\n  quantity       Float? // Khối lượng / Số lượng lô hàng\n  unit           String // Đơn vị tính (KG, Tấn, Thùng...)\n  status         BatchStatus   @default(PLANTED)\n  activities     ActivityLog[] // Lưu lịch sử canh tác\n  minTemperature Float // Nhiệt độ bảo quản tối thiểu (°C)\n  maxTemperature Float // Nhiệt độ bảo quản tối đa (°C)\n  minHumidity    Float // Độ ẩm bảo quản tối thiểu (%)\n  maxHumidity    Float // Độ ẩm bảo quản tối đa (%)\n  imageUrl       String        @default(\"/logo.png\")\n\n  // Quan hệ tác nhân gieo trồng\n  farmerId String\n  farmer   User   @relation(\"FarmerBatches\", fields: [farmerId], references: [id])\n\n  // Lịch sử thời gian\n  harvestDate DateTime? // Ngày thu hoạch thực tế\n  expiryDate  DateTime? // Hạn sử dụng dự kiến\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  retailCompanyId String?\n  retailCompany   Company? @relation(\"RetailerBatches\", fields: [retailCompanyId], references: [id])\n\n  shipperCompanyId String?\n  shipperCompany   Company? @relation(\"ShipperBatches\", fields: [shipperCompanyId], references: [id])\n\n  // Mối quan hệ các chặng hành trình\n  transits    StepTransit[]\n  qualityTest QualityTest?\n}\n\n// 3. CHI TIẾT HÀNH TRÌNH VẬN CHUYỂN (TRANSPORT LOGS)\n// Nhật ký ghi lại từng chặng đi của Shipper. Mỗi lần quét mã QR khi nhận/giao hàng sẽ tạo 1 bản ghi.\nmodel StepTransit {\n  id      String @id @default(uuid())\n  batchId String\n  batch   Batch  @relation(fields: [batchId], references: [id], onDelete: Cascade)\n\n  shipperId String\n  shipper   User   @relation(\"ShipperTransports\", fields: [shipperId], references: [id])\n\n  txHash        String? // Mã giao dịch trên Blockchain xác nhận chặng vận chuyển này là bất biến\n  fromLocation  String\n  toLocation    String\n  temperature   Float // Nhiệt độ bảo quản lúc vận chuyển (Rất quan trọng với chuỗi cung ứng lạnh)\n  humidity      Float // Độ ẩm bảo quản\n  vehicleNumber String // Biển số xe vận chuyển\n  departureTime DateTime @default(now())\n}\n\nmodel QualityTest {\n  id      String @id @default(uuid())\n  batchId String @unique // 1 lô hàng chỉ có 1 kết quả kiểm định chính thức\n  batch   Batch  @relation(fields: [batchId], references: [id], onDelete: Cascade)\n\n  retailerId String\n  retailer   User   @relation(\"RetailerTests\", fields: [retailerId], references: [id])\n\n  txHash   String? // Transaction Hash kiểm định bất biến trên blockchain\n  isPassed Boolean\n  note     String // Ghi chú lý do Đạt/Không Đạt (Lưu off-chain)\n  testedAt DateTime @default(now())\n}\n",
